/** The integrated annual report the app writes: sections carried by at least `min` of the 49 reports, in their median order. */
export function blueprint(min = 8) {
  const parts: Part[] = ['strategic', 'governance', 'financial'];
  return parts.map((part) => ({ part, ar: ({ strategic: 'التقرير الاستراتيجي', governance: 'الحوكمة', financial: 'القوائم المالية وتقرير المراجع', other: 'أخرى' } as const)[part],
    sections: SECTIONS.filter((s) => s.part === part && s.reports >= min).sort((a, b) => a.pos - b.pos) }));
}

